// A to-do list you can tap: a row ticks itself off, the header counts, and the
// row under the mouse offers what a tap would do (group-hover:).
const items = [
  { text: 'Water the plants', done: true },
  { text: 'Call grandma about Sunday', done: false },
  { text: 'Book the dentist', done: false },
  { text: 'Oat milk, coffee beans, lemons', done: false },
  { text: 'Take the recycling out', done: false },
]

const Check = () => (
  <svg className="w-5 h-5 text-white" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round">
    <path d="M5 12l5 5L20 7" />
  </svg>
)

export function get(app) {
  const done = items.filter((item) => item.done).length
  return (
    <div className="flex flex-col gap-3 p-8 bg-slate-100 text-slate-800">
      <div className="flex items-end justify-between">
        <span className="text-4xl font-bold">Today</span>
        <span className="text-xl text-slate-500">{`${done} of ${items.length} done`}</span>
      </div>
      <div className="h-2 rounded-full bg-slate-200">
        <div className={`h-2 rounded-full bg-emerald-500 w-[${(done * 100) / items.length}%]`} />
      </div>
      {items.map((item) => (
        <div className="group flex items-center gap-4 rounded-xl bg-white px-5 py-3 hover:bg-sky-50"
          onClick={() => { item.done = !item.done }}>
          <div className={`w-7 h-7 rounded-full flex items-center justify-center ${item.done ? 'bg-emerald-500' : 'border-2 border-slate-300'}`}>
            {item.done ? <Check /> : null}
          </div>
          <span className={`flex-1 text-xl ${item.done ? 'line-through text-slate-400' : ''}`}>{item.text}</span>
          <span className="text-sm font-semibold text-sky-600 opacity-0 group-hover:opacity-100">{item.done ? 'Undo' : 'Mark done'}</span>
        </div>
      ))}
    </div>
  )
}
